def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    """
    Granskar åtkomstloggar och returnerar en lista på IP-adresser 
    som inte finns med i listan över tillåtna IP-adresser.
    """
    unauthorized_ips = set()
    allowed_set = set(allowed_ips)

    try:
        with open(log_path, 'r') as file:
            for line in file:
                # Antagande: IP-adressen är det första elementet i varje rad
                ip = line.split()[0] if line.strip() else None
                if ip and ip not in allowed_set:
                    unauthorized_ips.add(ip)
    except FileNotFoundError:
        print(f"Error: Loggfilen på {log_path} hittades inte.")
        return []

    return list(unauthorized_ips)
```

